export class Vector4 {
    x;
    y;
    z;
    w;
    constructor(x = 0, y = 0, z = 0, w = 0) {
        this.x = x;
        this.y = y;
        this.z = z;
        this.w = w;
    }
    set(x, y, z, w) { this.x = x; this.y = y; this.z = z; this.w = w; return this; }
    copy(value) { return this.set(value.x, value.y, value.z, value.w); }
    clone() { return new Vector4(this.x, this.y, this.z, this.w); }
    multiplyScalar(value) { return this.set(this.x * value, this.y * value, this.z * value, this.w * value); }
    dot(value) { return this.x * value.x + this.y * value.y + this.z * value.z + this.w * value.w; }
}